import React, { useCallback, useMemo } from 'react';

import { ChipsSelect } from 'components/Form';
import type { Option } from 'models/Filters';
import {
  deriveTimePeriodSelection,
  formatTimePeriodLabel,
  getDefaultTimePeriodEnd,
  isHalfKey,
  isPeriodTypeEnabled,
  isQuarterKey,
  isYearMonth,
  normalizeTimePeriodType,
  parseDtEndToTimePeriodEnd,
  TimePeriodType,
} from 'utils/timePeriod/timePeriodAvailability';

import { TimePeriodFullYearSlider } from './components/TimePeriodFullYearSlider';
import { TimePeriodHalfSelector } from './components/TimePeriodHalfSelector';
import { TimePeriodMonthSlider } from './components/TimePeriodMonthSlider';
import { TimePeriodQuarterSelector } from './components/TimePeriodQuarterSelector';
import {
  ChipAbbreviation,
  Panel,
  PanelBody,
  PanelFooter,
  PeriodValueGroup,
  RangeHeader,
  RangeHeadlineText,
  RangeLabelText,
  RangeSublineText,
  TimeRangeSection,
} from './TimePeriodSelector.styles';
import type { TimePeriodEnd, TimePeriodSelectorProps } from './types';

const getChipAbbreviation = (periodType: TimePeriodType): string | null => {
  if (periodType === TimePeriodType.HALF) return null;
  return periodType;
};

const renderTimePeriodOptionLabel = (option: Option) => {
  const periodType = normalizeTimePeriodType(option.value);
  const abbreviation = periodType ? getChipAbbreviation(periodType) : null;

  return (
    <>
      <span style={{ fontSize: '14px' }}>{option.label}</span>{' '}
      {abbreviation && (
        <ChipAbbreviation
          data-testid={`time-period-chip-abbreviation-${option.value}`}
        >
          {abbreviation}
        </ChipAbbreviation>
      )}
    </>
  );
};

export function TimePeriodSelector({
  periodTypes,
  maxDtEnd,
  selectedType,
  selectedDtEnd,
  onChange,
  footer,
  variant = 'default',
}: Readonly<TimePeriodSelectorProps>) {
  const cutoffYear = Number(maxDtEnd.slice(0, 4));
  const normalizedSelectedType = normalizeTimePeriodType(selectedType);
  const selectedEnd = parseDtEndToTimePeriodEnd(
    normalizedSelectedType,
    selectedDtEnd,
  );

  const emitChange = useCallback(
    (type: string, end: TimePeriodEnd) => {
      const periodType = normalizeTimePeriodType(type);
      const selection = deriveTimePeriodSelection(periodType, end, maxDtEnd);
      if (selection) onChange(selection);
    },
    [maxDtEnd, onChange],
  );

  const handleChipClick = useCallback(
    (type: TimePeriodType) => {
      emitChange(type, getDefaultTimePeriodEnd(type, maxDtEnd));
    },
    [maxDtEnd, emitChange],
  );

  const timePeriodOptions = useMemo<Option[]>(
    () =>
      periodTypes.map((option) => ({
        ...option,
        isDisabled:
          option.isDisabled ||
          !isPeriodTypeEnabled(String(option.value), maxDtEnd),
      })),
    [maxDtEnd, periodTypes],
  );

  const handleEndChange = useCallback(
    (end: TimePeriodEnd) => {
      emitChange(normalizedSelectedType, end);
    },
    [emitChange, normalizedSelectedType],
  );

  const selectedPeriod = deriveTimePeriodSelection(
    normalizedSelectedType,
    selectedEnd,
    maxDtEnd,
  );
  const displayYear =
    normalizedSelectedType === TimePeriodType.FY
      ? Number(selectedPeriod?.dtEnd.slice(0, 4) ?? cutoffYear)
      : cutoffYear;
  const primaryLabel = formatTimePeriodLabel(
    normalizedSelectedType,
    selectedEnd,
    displayYear,
  );
  const description = selectedPeriod?.description ?? '';
  const selectedMonthEnd = isYearMonth(selectedEnd) ? selectedEnd : null;
  const selectedQuarterEnd = isQuarterKey(selectedEnd) ? selectedEnd : null;
  const selectedHalfEnd = isHalfKey(selectedEnd) ? selectedEnd : null;

  return (
    <Panel data-testid="time-period-selector" $variant={variant}>
      <PanelBody $variant={variant}>
        <ChipsSelect
          dataTestId="time-period-chips"
          options={timePeriodOptions}
          value={normalizedSelectedType}
          renderOptionLabel={renderTimePeriodOptionLabel}
          onChange={(option) => handleChipClick(option.value as TimePeriodType)}
          variant="rounded"
        />

        <TimeRangeSection>
          <div data-testid="time-period-label">
            <RangeHeader>
              <RangeLabelText>Time Period:</RangeLabelText>
              <PeriodValueGroup>
                <RangeHeadlineText data-testid="time-period-primary-label">
                  {primaryLabel}
                </RangeHeadlineText>
                {description && (
                  <RangeSublineText data-testid="time-period-range-label">
                    {description}
                  </RangeSublineText>
                )}
              </PeriodValueGroup>
            </RangeHeader>
          </div>

          {(normalizedSelectedType === TimePeriodType.YTD ||
            normalizedSelectedType === TimePeriodType.R3M ||
            normalizedSelectedType === TimePeriodType.MTH) && (
            <TimePeriodMonthSlider
              type={normalizedSelectedType}
              cutoffDate={maxDtEnd}
              selectedEnd={selectedMonthEnd}
              onEndChange={handleEndChange}
            />
          )}

          {normalizedSelectedType === TimePeriodType.QTR && (
            <TimePeriodQuarterSelector
              cutoffDate={maxDtEnd}
              selectedEnd={selectedQuarterEnd}
              onEndChange={handleEndChange}
            />
          )}

          {normalizedSelectedType === TimePeriodType.HALF && (
            <TimePeriodHalfSelector
              cutoffDate={maxDtEnd}
              selectedEnd={selectedHalfEnd}
              onEndChange={handleEndChange}
            />
          )}

          {normalizedSelectedType === TimePeriodType.FY && (
            <TimePeriodFullYearSlider />
          )}
        </TimeRangeSection>
      </PanelBody>

      {footer && <PanelFooter>{footer}</PanelFooter>}
    </Panel>
  );
}
